import { AUTO_HIDDEN_GAMES, type AutoHiddenGame, type HiddenGameReason } from "@/lib/autoHiddenGames";

// Two sources feed the hidden list:
//   - AUTO_HIDDEN_GAMES: generated by scripts/check-games.mjs on every scan.
//   - Runtime detections: a game that failed to load in a visitor's browser is
//     remembered locally so the same dead embed is not offered again.
// Hiding is never destructive: the Hidden filter still lists every hidden game
// and "Restore" puts it back in the main catalog.

export type { HiddenGameReason };

export interface HiddenGameEntry {
  reason: HiddenGameReason;
  detail: string;
  source: "auto" | "runtime";
}

const RUNTIME_HIDDEN_KEY = "polytrack_runtime_hidden_games";
const RESTORED_KEY = "polytrack_restored_games";
const HIDDEN_EVENT = "polytrack_hidden_games_updated";

type RuntimeHidden = Record<string, { reason: HiddenGameReason; detail: string; detectedAt: string }>;

function readJson<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
}

function writeJson(key: string, value: unknown) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {}
}

function isReason(value: unknown): value is HiddenGameReason {
  return value === "blank" || value === "not-found" || value === "offsite" || value === "error";
}

export function loadRuntimeHiddenGames(): RuntimeHidden {
  const parsed = readJson<unknown>(RUNTIME_HIDDEN_KEY, {});
  if (!parsed || typeof parsed !== "object") return {};
  const result: RuntimeHidden = {};
  for (const [id, entry] of Object.entries(parsed as Record<string, unknown>)) {
    if (!id || !entry || typeof entry !== "object") continue;
    const value = entry as Record<string, unknown>;
    if (!isReason(value.reason)) continue;
    result[id] = {
      reason: value.reason,
      detail: typeof value.detail === "string" ? value.detail : "",
      detectedAt: typeof value.detectedAt === "string" ? value.detectedAt : new Date().toISOString(),
    };
  }
  return result;
}

export function loadRestoredGameIds(): Set<string> {
  const parsed = readJson<unknown>(RESTORED_KEY, []);
  return new Set(
    Array.isArray(parsed) ? parsed.filter((id): id is string => typeof id === "string" && id.length > 0) : [],
  );
}

/**
 * Every game currently hidden from the main catalog, keyed by game id.
 */
export function loadHiddenGames(): Record<string, HiddenGameEntry> {
  const restored = loadRestoredGameIds();
  const runtime = loadRuntimeHiddenGames();
  const hidden: Record<string, HiddenGameEntry> = {};

  for (const [id, entry] of Object.entries(AUTO_HIDDEN_GAMES)) {
    if (restored.has(id)) continue;
    hidden[id] = { reason: entry.reason, detail: entry.detail, source: "auto" };
  }
  for (const [id, entry] of Object.entries(runtime)) {
    if (restored.has(id)) continue;
    hidden[id] = { reason: entry.reason, detail: entry.detail, source: "runtime" };
  }
  return hidden;
}

/**
 * Marks a game as broken. Called by the game launcher when an embed fails.
 */
export function hideGame(id: string, reason: HiddenGameReason, detail: string): void {
  if (!id) return;
  const runtime = loadRuntimeHiddenGames();
  runtime[id] = { reason, detail, detectedAt: new Date().toISOString() };
  writeJson(RUNTIME_HIDDEN_KEY, runtime);

  const restored = loadRestoredGameIds();
  if (restored.delete(id)) writeJson(RESTORED_KEY, Array.from(restored));

  dispatchChange();
}

/**
 * Brings a hidden game back into the main catalog, overriding both the scan and
 * any local detection.
 */
export function restoreGame(id: string): void {
  if (!id) return;
  const restored = loadRestoredGameIds();
  restored.add(id);
  writeJson(RESTORED_KEY, Array.from(restored));

  const runtime = loadRuntimeHiddenGames();
  if (id in runtime) {
    delete runtime[id];
    writeJson(RUNTIME_HIDDEN_KEY, runtime);
  }

  dispatchChange();
}

export function isGameHidden(id: string): boolean {
  return !!loadHiddenGames()[id];
}

function dispatchChange() {
  try {
    window.dispatchEvent(new CustomEvent(HIDDEN_EVENT));
  } catch {}
}

export function onHiddenGamesChange(callback: (hidden: Record<string, HiddenGameEntry>) => void): () => void {
  const handler = () => callback(loadHiddenGames());
  const storageHandler = (event: StorageEvent) => {
    if (event.key === RUNTIME_HIDDEN_KEY || event.key === RESTORED_KEY) handler();
  };
  window.addEventListener(HIDDEN_EVENT, handler);
  window.addEventListener("storage", storageHandler);
  return () => {
    window.removeEventListener(HIDDEN_EVENT, handler);
    window.removeEventListener("storage", storageHandler);
  };
}

export type { AutoHiddenGame };
